#!/usr/bin/env node
// Writes .github/cli/, the lockfile the composite action installs the apify-test-tools CLI from.
//
//     node .github/scripts/sync-cli-lockfile.mjs           # regenerate after changing dependencies
//     node .github/scripts/sync-cli-lockfile.mjs --check   # CI: fail if it is out of date
//
// It is the root package-lock.json cut down to the package's runtime dependencies, so the workflows
// run the CLI on exactly the versions this repo tested, integrity hashes included. Nothing is
// resolved from the registry: npm runs offline and only drops what the runtime dependencies don't
// need. It lives outside the package's own package.json, so people installing apify-test-tools
// normally still get regular semver resolution.

import { spawnSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

const ROOT = path.resolve(import.meta.dirname, '../..');
const CLI_DIR = path.join(ROOT, '.github/cli');
const FILES = ['package.json', 'package-lock.json'];
const check = process.argv.includes('--check');

const rootPackage = JSON.parse(fs.readFileSync(path.join(ROOT, 'package.json'), 'utf8'));
const cliPackage = {
    name: 'apify-test-tools-workflows-cli',
    private: true,
    description: 'Generated by .github/scripts/sync-cli-lockfile.mjs, do not edit.',
    dependencies: rootPackage.dependencies,
};

const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'cli-lockfile-'));
try {
    fs.writeFileSync(path.join(tmp, 'package.json'), `${JSON.stringify(cliPackage, null, 4)}\n`);
    fs.copyFileSync(path.join(ROOT, 'package-lock.json'), path.join(tmp, 'package-lock.json'));
    const npm = spawnSync(
        'npm',
        ['install', '--package-lock-only', '--offline', '--ignore-scripts', '--no-audit', '--no-fund'],
        { cwd: tmp, stdio: 'inherit' },
    );
    if (npm.status !== 0) {
        console.error('npm could not derive the CLI lockfile from package-lock.json. Is package-lock.json in sync?');
        process.exit(1);
    }

    if (check) {
        const stale = FILES.filter((file) => {
            const committed = path.join(CLI_DIR, file);
            return (
                !fs.existsSync(committed) ||
                fs.readFileSync(committed, 'utf8') !== fs.readFileSync(path.join(tmp, file), 'utf8')
            );
        });
        if (stale.length > 0) {
            console.error(
                `.github/cli/ is out of date with package.json / package-lock.json (${stale.join(', ')}).\n` +
                    'Run `node .github/scripts/sync-cli-lockfile.mjs` and commit the result.',
            );
            process.exit(1);
        }
        console.log('.github/cli/ matches the runtime dependencies in package-lock.json.');
    } else {
        fs.mkdirSync(CLI_DIR, { recursive: true });
        for (const file of FILES) fs.copyFileSync(path.join(tmp, file), path.join(CLI_DIR, file));
        console.log('Wrote .github/cli/.');
    }
} finally {
    fs.rmSync(tmp, { recursive: true, force: true });
}
